solution:
fn largest[T: Ord + Clone](items: &Vec[T]) -> T
  requires: items.len() > 0;
  ensures: result == items[0] || result > items[0];
{
  var max = items[0].clone();
  for item in items {
    if item > max { max = item.clone(); }
  }
  return max;
}

fn main() -> Int {
  let v = Vec[Int]();
  v.push(3); v.push(7); v.push(2); v.push(9); v.push(1);
  return largest[Int](&v);
}
